SELECT * FROM forecast_version
AND (version_no LIKE CONCAT('%', #{keyword}, '%') OR status LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id DESC LIMIT #{offset}, #{pageSize}

SELECT * FROM forecast_detail 
WHERE version_id = #{versionId} AND material_id = #{materialId}
ORDER BY plan_month

SELECT * FROM forecast_detail
version_id = #{versionId}
AND (material_id LIKE CONCAT('%', #{keyword}, '%') OR material_name LIKE CONCAT('%', #{keyword}, '%') OR factory_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY material_id, plan_month LIMIT #{offset}, #{pageSize}

SELECT DISTINCT material_id, material_name, factory_code, form_type, project, platform, mold, status FROM forecast_detail
version_id = #{versionId}
AND (material_id LIKE CONCAT('%', #{keyword}, '%') OR material_name LIKE CONCAT('%', #{keyword}, '%') OR factory_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY material_id LIMIT #{offset}, #{pageSize}

SELECT COUNT(DISTINCT material_id) FROM forecast_detail
version_id = #{versionId}
AND (material_id LIKE CONCAT('%', #{keyword}, '%') OR material_name LIKE CONCAT('%', #{keyword}, '%') OR factory_code LIKE CONCAT('%', #{keyword}, '%'))

SELECT COUNT(*) FROM forecast_detail
version_id = #{versionId}
AND (material_id LIKE CONCAT('%', #{keyword}, '%') OR material_name LIKE CONCAT('%', #{keyword}, '%') OR factory_code LIKE CONCAT('%', #{keyword}, '%'))
